const slug=value=>String(value||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,42);
const titleCase=value=>String(value||'').replaceAll('-',' ').replace(/\b\w/g,letter=>letter.toUpperCase());
const makeEquipment=(countryId,row,tier)=>{
 const [name,category,manufacture,originCountryId]=row,base=TIER_BLUEPRINTS[tier],bonus=CATEGORY_STAT_BONUS[category]||{};
 const domain=['multirole','advanced','air-defense'].includes(category)?'air':['littoral-support','maritime-command','fleet-network'].includes(category)?'sea':'land';
 const stats=Object.fromEntries(Object.entries(base.stats).map(([key,value])=>[key,value+(bonus[key]||0)]));
 const capabilities=domain==='land'?{pressure:stats.presence+stats.precision*.35,control:stats.presence*.75+stats.mobility*.45,protection:stats.protection+stats.support*.25,reach:stats.mobility*.55+stats.precision*.2,support:stats.support}:domain==='air'?{pressure:stats.precision*.8+stats.mobility*.35,control:stats.precision*.45+stats.support*.3,protection:stats.protection*.7+stats.mobility*.25,reach:stats.mobility+stats.precision*.35,support:stats.support*.8}: {pressure:stats.precision*.55+stats.presence*.45,control:stats.presence*.55+stats.support*.45,protection:stats.protection*.8+stats.support*.3,reach:stats.mobility*.75+stats.support*.4,support:stats.support};
 const packageSize=domain==='air'?12:domain==='sea'?4:24,unitCostUsd=[0,5_000_000,12_000_000,28_000_000,65_000_000,95_000_000][tier];
 return {id:`${countryId.toLowerCase()}-${slug(name)}`,countryId,name,tier,category,role:category,domain,capabilities:Object.fromEntries(Object.entries(capabilities).map(([key,value])=>[key,Math.round(value*10)/10])),manufacture,originCountryId,manufacturerId:COMPANY_BY_COUNTRY[countryId],developmentNodeId:CATEGORY_DEVELOPMENT[category]||DEVELOPMENT_BY_TIER[tier],cost:base.cost,buildTurns:base.buildTurns,upkeep:base.upkeep,supply:base.supply,manpower:80+tier*70,stats,exportRule:null,packageSize,unitCostUsd,acquisitionCostUsd:unitCostUsd*packageSize,costBasis:'Simulation estimate where no comparable public program figure is available.',specs:{crew:'Varies by formation',range:'Mission dependent',speed:'Platform dependent',manufacturer:'National industrial network'}};
};

