function factoryType(id){return CAMPAIGN_FACTORY_TYPES.find(item=>item.id===id)}
function baseType(id){return CAMPAIGN_BASE_TYPES.find(item=>item.id===id)}
function factoryCanProduce(factory,item){const type=factoryType(factory?.typeId);if(!type||!item)return false;if(type.id==='airframe-complex')return item.domain==='air';if(type.id==='naval-shipyard')return item.domain==='sea';if(type.id==='land-systems-works')return item.domain==='land';if(type.id==='general-assembly')return item.tier<=2||type.capabilities.includes(item.platformClass)||type.capabilities.includes(item.category);return type.capabilities.some(tag=>[item.platformClass,item.category,item.role].map(value=>String(value||'').toLowerCase()).some(value=>value.includes(tag)))}
